//! The space tools' descriptions and argument texts (src/shared/core/space-tools.ts). They go to
//! outside agents, lessons and deadline requests, so they stay word for word the same as the TypeScript's.

use std::sync::LazyLock;

use crate::contracts::space::{SPACE_ICONS, SIGNATURE_MAX};

/// Each tool's description, by tool name, in source order.
pub const SPACE_TOOL_TEXT: [(&str, &str); 16] = [
	("list_spaces", "List learner's spaces, closed ones included, with file and lesson counts."),
	("read_space", "Read one space: description, file counts per status (pending, extracting, ready, failed, needs-whisper) and files that couldn't be read, knowledge-graph topics with fact counts, deadlines (kind, date, time, done, files each covers), outOfDate when one looks missing, path (each topic's status, what the next covers), lessons, today's local date and time. files: true lists every file instead (id, kind, status, size, path on disk). To find something inside files: search_space_files."),
	("search_space_files", "Search all of a space's files (readings, slides, transcripts, syllabus, assignments) by meaning and keywords. Returns best passages, each with id, file, place (page, slide, time or lines) and short snippet. Open needed ones with read_passage, not whole files."),
	("read_passage", "Read one passage of a space file by its id from search_space_files, or a file's passages at a place (file_id + range, e.g. a whole page). Returns text with ids of passages before and after, to keep reading."),
	("create_space", "Create a space for one thing the learner studies (university course, certification, language). Description is shown to the teacher in every lesson of the space: level, book or source they follow, its notation, what they work toward (a course's exams, an interview). Add deadlines with add_space_deadline. A goal with no syllabus (a job, a skill): send path, the topics toward it in order, leaving out what the learner already knows."),
	("update_space", "Rename a space, change description, signature, icon or path, or close / reopen it (closing hides its tab, keeps everything; closed space takes no new lessons)."),
	("add_space_file", "Copy a file from this computer into a space, or write one with name and text instead of path (one you wrote before by that name is replaced, keeps its id). A file you build for the learner (practice test, worksheet, its .tex source): build it in the godspeed folder's made/<space name>/ and add the finished file from there; adding it again by that name replaces it and keeps its id, and a .tex beside its PDF shows as one file. Supported: .md .txt, code files (.c .py .java .js and the like), plain text with no extension, .pdf .docx .pptx .epub, .vtt .srt (transcripts) and .mp3 .m4a .wav .mp4 .mov (recordings, transcribed locally with whisper.cpp). Google Docs links (.gdoc) need saving as PDF or Word first. Study files are turned into facts by you, through wait_for_work."),
	("set_space_file_kind", "Switch space files between study material and space info. Study → info removes their facts; info → study builds them. File that can't switch is listed under refused; others still switch."),
	("add_space_deadline", "Add one or more deadlines to a space (all of a space's deadlines in one call): exams, homework, quizzes, projects, interviews, each with date, time if any, and which space files (notes, readings) it covers. godspeed uses it to show the learner what's due and what to work on first. Take deadlines, dates and times from space info files (syllabus, schedule); never make up a date or time. Work out coverage from the space's own files first: practice exam or review sheet, schedule, announcements (search_space_files). Link files they point to (file_ids), list earlier files it doesn't cover in left_out_ids, name in source the file it came from. Ask only when files don't settle it. File ids from read_space with files: true. Refused deadlines are listed under refused with the reason; others still get added, so resend only refused ones. Interview: add the posting as space info, the interview with date and time, What it's like.md as about_file_id, and a Study guide.md you write (study) in file_ids."),
	("update_space_deadline", "Change a deadline's kind, name, date, time, covered files, left-out files, source, assignment file or about file, or tick done (done: true) / not done (done: false). file_ids and left_out_ids each replace the whole list (a file is never in both); time: null, source: null, assignment_file_id: null and about_file_id: null remove them. Work out coverage from space's own files as add_space_deadline says; ask the learner when files don't settle it."),
	("remove_space_deadline", "Remove one deadline from a space (its files and facts untouched)."),
	("link_space_folder", "Link a folder on this computer to a space. Supported files are added; from then on new files dropped there are added automatically and edited ones rebuilt (checked every minute while godspeed is open). godspeed sorts them into study material and space info itself while reading, never changes the folder. set_space_file_kind only to correct a kind."),
	("start_lesson", "Start or continue a study session in godspeed taught by you. topic: a new session; it becomes the learner's first message and the lesson's title in their top bar, so plain words, never file ids, paths or quoted file names; a path topic's name studies that topic. deadline_id alone: what the deadline's Study key does (continues the unfinished session for it the learner last worked in, else starts one on its topics); with homework: true, its Work on key (continues its latest homework session, else starts one). topic with deadline_id: a new session for that deadline that is not its Study session. topic alone, while a deadline of its space due within 2 days has an unfinished session: sent back once, naming it. file_ids: a lesson on these files (a test with its key, a chapter); the first names it; ids from read_space with files:true. With space_id the lesson belongs to that space: opens with the space's card, its facts go to that space's graph. You teach it through wait_for_work; learner follows in the godspeed window."),
	("open_page", "Open a page in the learner's godspeed window when they ask to see something (\"open my cheat sheet\"), even with Follow off; brings the window forward. Never jumps away from unsent lesson text, a running mock or an open dialog: then the window offers Go to instead."),
	("search_vault", "Search the learner's Obsidian vault, their own notes and godspeed's, by words. Returns each note's name, path, owner (you or godspeed), class, confidence and a short snippet. With path instead of query: that whole note, cut at 20,000 characters. The vault is read only with this tool, never with file tools, and is never added to a graph. Look here before writing a note, so a note the learner already has is linked, not repeated."),
	("write_vault_note", "Write what the learner answered about one idea into their Obsidian vault: a new note, or an update of godspeed's note for that topic (one note per topic). godspeed writes the file and its properties; you send the words. A note the learner changed is kept as they left it, and kept in the answer names what was left alone. If the learner already has a note on the idea, send covered_by (its path from search_vault) and nothing else: no note is written and the two are linked. waiting: the vault cannot be reached now, and the note is written once it can."),
];

/// The argument descriptions both tool schemas share.
pub struct SpaceArgText {
	pub files: &'static str,
	pub query: &'static str,
	pub limit: &'static str,
	pub passage_id: &'static str,
	pub file_id: &'static str,
	pub range: &'static str,
	pub name: &'static str,
	pub description: &'static str,
	pub signature: String,
	pub icon: String,
	pub file_path: &'static str,
	pub file_name: &'static str,
	pub file_text: &'static str,
	pub file_lesson: &'static str,
	pub folder_path: &'static str,
	pub file_kind: &'static str,
	pub file_ids: &'static str,
	pub deadline_kind: &'static str,
	pub deadline_name: &'static str,
	pub date: &'static str,
	pub time: &'static str,
	pub covered_files: &'static str,
	pub left_out_files: &'static str,
	pub source: &'static str,
	pub assignment_file: &'static str,
	pub about_file: &'static str,
	pub about_file_change: &'static str,
	pub new_time: &'static str,
	pub topic: &'static str,
	pub lesson_space: &'static str,
	pub lesson_deadline: &'static str,
	pub lesson_files: &'static str,
	pub homework: &'static str,
	pub page: &'static str,
	pub page_space: &'static str,
	pub page_deadline: &'static str,
	pub page_lesson: &'static str,
	pub path: &'static str,
	pub path_goal: &'static str,
	pub path_covers: &'static str,
	pub vault_topic: &'static str,
	pub vault_title: &'static str,
	pub vault_text: &'static str,
	pub vault_recall: &'static str,
	pub vault_mistakes: &'static str,
	pub vault_mistake_text: &'static str,
	pub vault_mistake_kind: &'static str,
	pub vault_mistake_id: &'static str,
	pub vault_source: &'static str,
	pub vault_links: &'static str,
	pub vault_covered_by: &'static str,
	pub vault_asked: &'static str,
	pub vault_query: &'static str,
	pub vault_path: &'static str,
	pub vault_limit: &'static str,
	pub vault_space: &'static str,
}

